


/** Requested tip expressed as either a flat amount or a percentage. Send exactly one of amount_money or percent. */ export type CreateOrderTipInput = ({ /** Flat requested tip in the order currency. The amount must be at least 1 minor unit; otherwise, Flint returns INVALID_TIP_AMOUNT. For USD orders, the maximum is the larger of $1,000 or the post-discount merchandise subtotal. */ "amount_money"?: ({ /** Use an exact numeric string, not a floating-point number. Format: int64. minimum: 1. */ "amount"?: string; }) & ({ /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }); "description"?: string; "metadata"?: Record<string, string>; "name"?: string; /** Requested tip percentage from 1 through 100, calculated from the post-discount merchandise subtotal. minimum: 1. maximum: 100. multipleOf: 0.0001. */ "percent"?: number; }) & ((({ "amount_money": unknown; }) & (({ "percent"?: never }))) | (({ "percent": unknown; }) & (({ "amount_money"?: never }))));
